import org.example.utilities.StringUtils

import org.apache.commons.text.WordUtils

fun greeting(): String {
    val tokens = StringUtils.split(MessageUtils.getMessage())
    val result = StringUtils.join(tokens)
    return WordUtils.capitalize(result)
}

@Composable
fun AppScreen() {
    var clicks by remember { mutableStateOf(0) }

    MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
            Column(
                modifier = Modifier.fillMaxSize().padding(24.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp, Alignment.CenterVertically),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                Text(greeting(), style = MaterialTheme.typography.headlineMedium)
                Text("Pulsaciones: $clicks")
                Button(onClick = { clicks++ }) {
                    Text("Pulsar")
                }
            }
        }
    }
}

fun main() = application {
    // Phone-sized window to preview how the screen will look on Android.
    Window(
        onCloseRequest = ::exitApplication,
        title = "auto_play",
        state = rememberWindowState(size = DpSize(400.dp, 800.dp)),
    ) {
        AppScreen()
    }
}
